window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f2cf34851b54f3b"]={"versions": [{"id": "FIG-9f2cf34851b54f3b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcenmodells (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm definiert die Modellierungsstruktur und Metaklassen für Kommunikationsperipheriebausteine (<code>CommunicationPeripheral</code>) innerhalb der Hardware-Beschreibung einer ECU, einschließlich ihrer Einbettung in die Peripheriehierarchie und ihrer Assoziationen zu Protokollen, Filtern, Takten, Ports und Fehlererkennungsmechanismen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Peripheral</strong> (Spezialisierung von <code>HWElement</code>): Abstrakte Basisklasse für Peripheriekomponenten mit dem optionalen Attribut <code>canBeDisabled: Boolean [0..1]</code>.</li>\n<li><strong>CommunicationPeripheral</strong> (erbt von <code>Peripheral</code>): Zentrales Element zur Beschreibung eines Kommunikationscontrollers. Attribute:</li>\n<li><code>architecture: Enumeration{master, slave, multiMaster} [0..1]</code></li>\n<li><code>monitor: Boolean [0..1]</code></li>\n<li><code>timestamp: Boolean [0..1]</code></li>\n<li><strong>CommunicationHWPort</strong> (Spezialisierung von <code>PeripheralHWPort</code>): Komposition <code>+hwPort</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong>Clock</strong> (aus Kontext/Package <code>ECUElectronics</code>): Gerichtete Assoziation <code>+clock</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>CommunicationProtocol</strong> (spezialisiert <code>Identifiable</code>): Aggregation <code>+protocol</code> mit Multiplizität <code>1..<em></code> und Attribut <code>version: String [1..</em>]</code>.</li>\n<li><strong>CommunicationFilter</strong>:</li>\n<li>Komposition <code>+ACCEPTANCE-FILTER</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+REJECTION-FILTER</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Attribute: <code>filterCount: Int</code>, <code>filterWidth: Int</code>, <code>wildCards: Boolean [0..1]</code>.</li>\n<li><strong>ErrorDetectionCorrection</strong>: Komposition <code>+errorDetection</code> mit Multiplizität <code>0..1</code>. Attribute: <code>extraBits: Int</code>, <code>detectedBits: Int</code>, <code>correctedBits: Int</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Konfigurations- und Hardware-Struktur zur Modellierungs- bzw. Entwurfszeit einer ECU, nicht das dynamische Laufzeitverhalten während der Nachrichtenübertragung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell ist normativ für AUTOSAR-ECU-Ressourcenbeschreibungen:</p>\n<ul class=\"fig-list\">\n<li>Eine <code>CommunicationPeripheral</code> muss mindestens ein <code>CommunicationProtocol</code> referenzieren (<code>1..*</code>).</li>\n<li>Hardwareschnittstellen (<code>CommunicationHWPort</code>) können mehrfach vorliegen (<code>0..*</code>).</li>\n<li>Akzeptanz- und Rejektionsfilter (<code>CommunicationFilter</code>) sowie Fehlerkorrektur-/Erkennungsmechanismen (<code>ErrorDetectionCorrection</code>) sind optional (<code>0..1</code>).</li>\n<li>Taktanbindung (<code>Clock</code>) erfolgt als gerichtete Referenz mit Multiplizität <code>0..1</code>.</li>\n</ul>"}, {"id": "FIG-ab8d1e9845bb8919", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcenmodells (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm definiert die Modellierungsstruktur und Metaklassen für Kommunikationsperipheriebausteine (<code>CommunicationPeripheral</code>) innerhalb der Hardware-Beschreibung einer ECU, einschließlich ihrer Einbettung in die Peripheriehierarchie und ihrer Assoziationen zu Protokollen, Filtern, Takten, Ports und Fehlererkennungsmechanismen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Peripheral</strong> (Spezialisierung von <code>HWElement</code>): Abstrakte Basisklasse für Peripheriekomponenten mit dem optionalen Attribut <code>canBeDisabled: Boolean [0..1]</code>.</li>\n<li><strong>CommunicationPeripheral</strong> (erbt von <code>Peripheral</code>): Zentrales Element zur Beschreibung eines Kommunikationscontrollers. Attribute:</li>\n<li><code>architecture: Enumeration{master, slave, multiMaster} [0..1]</code></li>\n<li><code>monitor: Boolean [0..1]</code></li>\n<li><code>timestamp: Boolean [0..1]</code></li>\n<li><strong>CommunicationHWPort</strong> (Spezialisierung von <code>PeripheralHWPort</code>): Komposition <code>+hwPort</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong>Clock</strong> (aus Kontext/Package <code>ECUElectronics</code>): Gerichtete Assoziation <code>+clock</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>CommunicationProtocol</strong> (spezialisiert <code>Identifiable</code>): Aggregation <code>+protocol</code> mit Multiplizität <code>1..<em></code> und Attribut <code>version: String [1..</em>]</code>.</li>\n<li><strong>CommunicationFilter</strong>:</li>\n<li>Komposition <code>+ACCEPTANCE-FILTER</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Komposition <code>+REJECTION-FILTER</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Attribute: <code>filterCount: Int</code>, <code>filterWidth: Int</code>, <code>wildCards: Boolean [0..1]</code>.</li>\n<li><strong>ErrorDetectionCorrection</strong>: Komposition <code>+errorDetection</code> mit Multiplizität <code>0..1</code>. Attribute: <code>extraBits: Int</code>, <code>detectedBits: Int</code>, <code>correctedBits: Int</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Konfigurations- und Hardware-Struktur zur Modellierungs- bzw. Entwurfszeit einer ECU, nicht das dynamische Laufzeitverhalten während der Nachrichtenübertragung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell ist normativ für AUTOSAR-ECU-Ressourcenbeschreibungen:</p>\n<ul class=\"fig-list\">\n<li>Eine <code>CommunicationPeripheral</code> muss mindestens ein <code>CommunicationProtocol</code> referenzieren (<code>1..*</code>).</li>\n<li>Hardwareschnittstellen (<code>CommunicationHWPort</code>) können mehrfach vorliegen (<code>0..*</code>).</li>\n<li>Akzeptanz- und Rejektionsfilter (<code>CommunicationFilter</code>) sowie Fehlerkorrektur-/Erkennungsmechanismen (<code>ErrorDetectionCorrection</code>) sind optional (<code>0..1</code>).</li>\n<li>Taktanbindung (<code>Clock</code>) erfolgt als gerichtete Referenz mit Multiplizität <code>0..1</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-9f2cf34851b54f3b", "to": "FIG-ab8d1e9845bb8919", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
